        Self(Cell::new(core::ptr::null_mut()))
    }

    /// Whether a parse, or [`set`](Self::set), has stored a position.
    #[must_use]
    pub fn is_set(&self) -> bool {
        !self.0.get().is_null()
    }

    /// Stores the start of `tail`, the arguments from the first one a spec took, as C stores
