686	        ///
687	        /// fn shrink<'a, 'p>(s: SpecRef<'a, 'static>) -> SpecRef<'a, 'p> {
688	        ///     s
689	        /// }
690	        /// ```
691	        ///
692	        /// Neither `Send` nor `Sync`: its variables are [`Cell`]s, which a parse on another
693	        /// thread would race with.
694	        ///
695	        /// ```compile_fail,E0277
696	        /// use libgit2_crustify::git2::src::cli::opt::Spec;
697	        /// use ffibox::CZeroable;
698	        ///
699	        /// let spec: Spec<'static> = Spec::zeroed();
700	        /// std::thread::spawn(move || drop(spec));
