1040	    /// a `const cli_opt_spec[]` whose end is a spec of kind [`Kind::None`].
1041	    ///
1042	    /// Its length counts the specs before that end, which C never matches; the end itself
1043	    /// stays in memory after them, for C to stop at.
1044	    #[derive(Clone, Copy)]
1045	    pub struct SpecTable<'p> {
