1050	    impl<'p> SpecTable<'p> {
1051	        /// The table of `specs`, up to its first spec of kind [`Kind::None`], or `None` when
1052	        /// `specs` holds no such spec to end it.
1053	        #[must_use]
1054	        pub fn new(specs: &'p [Spec<'p>]) -> Option<Self> {
1055	            let len = specs.iter().position(|s| s.as_ref().raw_kind() == 0)?;
1056	            // SAFETY: `specs` is borrowed shared for `'p`, so its first `len` elements, ended by
1057	            // the spec at `len`, live and stay unchanged for `'p`.
1058	            let specs = unsafe { CSlice::from_raw_parts(NonNull::from(specs).cast(), len) };
1059	            Some(Self { specs })
1060	        }
