        ///
        /// Wraps `fld::cli_opt_parser.idx`
        #[doc(alias = "cli_opt_parser.idx")]
        pub fn set_idx(&mut self, idx: usize) {
            let p = self.as_mut_ptr();
            // SAFETY: `p` is the exclusive handle's pointer to the live parser it borrows; the
