        /// Sets how many of the table's [`Kind::Arg`] specs are done with.
        ///
        /// Wraps `fld::cli_opt_parser.arg_idx`
        #[doc(alias = "cli_opt_parser.arg_idx")]
        pub fn set_arg_idx(&mut self, arg_idx: usize) {
