/// pub struct HolderFree;
/// ffibox::impl_cdrop!(HolderFree, Holder<'_>, holder_free);
///
/// fn adopt<'p>(raw: *mut holder_st) -> Option<CBox<Holder<'p>, HolderFree>> {
