/// pub struct HolderFree;
/// ffibox::impl_cdrop!(HolderFree, Holder<'p>, holder_free); // `'_`, not `'p`
/// ```
///
/// A deep copy names the lifetime instead, `<'p> HolderFree, Holder<'p>`: see
/// [`impl_cdupclone!`](crate::impl_cdupclone).
///
/// # Safety
