    let rest = ArgsSlot::new();
    let targets = [
        Target::None,
        Target::Bool(Some(&flag)),
        Target::Switch(Some(&flag)),
        Target::Accumulator(Some(&flag)),
        Target::Value(Some(&value)),
        Target::Literal,
        Target::Arg(Some(&value)),
        Target::Args(Some(&rest)),
        Target::Bool(None),
        Target::Value(None),
        Target::Args(None),
