                assert_eq!(a.map(core::ptr::from_ref), b.map(core::ptr::from_ref));
            }
            (Target::None, Target::None) | (Target::Literal, Target::Literal) => {}
            _ => panic!("{target:?} read back as {read:?}"),
        }
